var o=[{title:`Comece com um ensaio fácil`,text:`Faça o movimento sem peso ou com o implemento mais leve que tiver. Acrescente uma pequena carga numa série de aquecimento e verifique se a amplitude de movimento, a respiração e o ritmo se mantêm estáveis. Cada movimento tem o seu próprio peso de trabalho: uma carga que parece confortável numa remada pode ser demasiado pesada para uma elevação lateral.`},{title:`Repetições de reserva`,text:`As repetições de reserva (RIR) são quantas repetições mais com boa execução acha que ainda conseguiria fazer. Para o treino geral, terminar muitas séries com cerca de duas ou três repetições de reserva é um ponto de partida prático, embora não tenha de o atingir sempre. Se numa série planeada de 10 sentir que conseguia fazer mais 10, a carga pode ser demasiado leve para o seu objetivo.`},{title:`Ajustar durante a sessão`,text:`Imagine que o plano pede três séries de oito a doze. Se a primeira série terminar em oito com técnica instável e sem nada de reserva, baixe a carga. Se doze repetições forem fluidas e ainda bastante fáceis, experimente um pequeno aumento na série seguinte. Descanse o tempo suficiente para perceber se foi o peso ou a fadiga que causou o problema.`},{title:`Quando os saltos de peso são grandes demais`,text:`Se o haltere seguinte for demasiado pesado, acrescente uma repetição, uma pausa controlada ou outra boa série. Se até o seu peso mais leve for demasiado pesado, use o peso do corpo, uma banda elástica ou uma alavanca diferente. Nunca force repetições falhadas para chegar a um número de série.`},{title:`Usar o TrainUp`,text:`O seu plano dá séries, repetições e descanso, mas não pesos, por isso escolhe a carga. Durante o treino, registe as repetições que realmente fez e, depois, avalie o esforço da sessão de 1 a 10. Se sentir dor, tonturas ou perder repetidamente a técnica, pare ou mude o exercício; não acrescente resistência. “Sinto dor” termina de imediato o exercício atual.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Resumo das orientações do ACSM 2026 sobre treino de resistência`,url:`https://acsm.org/resistance-training-guidelines-update-2026/`},{label:`Mayo Clinic: segurança e técnica no treino com pesos`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};